sys_notification.advanced_condition:
(function runMailScript(/*GlideRecord*/ current, /*TemplatePrinter*/ template,
                       /*Optional EmailOutbound*/ email, /*Optional Object*/ email_action,
                       /*Optional TransformMap*/ event) {

    template.print("<b>Timestamp:</b> " + current.sys_updated_on + "<br/>");

    // Check if risk score exceeds 80 to show automated lockout notice
    if (current.risk_score > 80) {
        template.print("<p style='color:red; font-weight:bold;'>CRITICAL ALERT: Risk score exceeded 80! Automatic safety lockout protocol initiated for this asset.</p>");
    } else {
        template.print("<p style='color:green;'>Status Normal: Usage logged successfully.</p>");
    }

})(current, template, email, email_action, event);

